import{_ as e,c as r,o as a,aj as o}from"./chunks/framework.C2N4vG9O.js";const m=JSON.parse('{"title":"Tutorial Overview","description":"Torch-RecHub scenario tutorials overview and entry points","frontmatter":{"title":"Tutorial Overview","description":"Torch-RecHub scenario tutorials overview and entry points"},"headers":[],"relativePath":"tutorials/intro.md","filePath":"en/tutorials/intro.md"}'),i={name:"tutorials/intro.md"};function l(d,t,s,h,n,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="tutorial-overview" tabindex="-1">Tutorial Overview <a class="header-anchor" href="#tutorial-overview" aria-label="Permalink to “Tutorial Overview”">​</a></h1><p>To check your installation, train DeepFM once with the <a href="/torch-rechub/guide/quick_start.html">Quick Start</a>. The three tutorials below use datasets included in the repository. Open a notebook or terminal at the repository root so the example paths resolve correctly.</p><h2 id="tutorial-list" tabindex="-1">Tutorial List <a class="header-anchor" href="#tutorial-list" aria-label="Permalink to “Tutorial List”">​</a></h2><ul><li><strong>Rank candidate ads.</strong> Predict the probability of a click on a Criteo impression, then use AUC to see how well the model ranks clicked ads above unclicked ones. <a href="/torch-rechub/tutorials/ctr.html">Ranking tutorial</a></li><li><strong>Retrieve candidate movies.</strong> Train DSSM on MovieLens, compute user and movie embeddings separately, and retrieve ten movies for one user. <a href="/torch-rechub/tutorials/retrieval.html">Retrieval tutorial</a></li><li><strong>Predict clicks and purchases together.</strong> Train MMOE or PLE with two Ali-CCP labels and inspect AUC for each task. The ESMM example also uses a label for impressions that led to both a click and a purchase. <a href="/torch-rechub/tutorials/pipeline.html">Multi-task tutorial</a></li></ul><h2 id="model-tutorials" tabindex="-1">Model Tutorials <a class="header-anchor" href="#model-tutorials" aria-label="Permalink to “Model Tutorials”">​</a></h2><p>If you already know which model you want, open its tutorial to see which fields it needs.</p><h3 id="ranking-models" tabindex="-1">Ranking Models <a class="header-anchor" href="#ranking-models" aria-label="Permalink to “Ranking Models”">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Summary</th><th>Link</th></tr></thead><tbody><tr><td>DeepFM</td><td>FM + deep network for ranking</td><td><a href="/torch-rechub/tutorials/models/ranking/deepfm.html">DeepFM</a></td></tr><tr><td>Wide&amp;Deep</td><td>A linear layer and a deep network score each impression</td><td><a href="/torch-rechub/tutorials/models/ranking/widedeep.html">Wide&amp;Deep tutorial</a></td></tr><tr><td>DCN / DCNv2</td><td>Explicit feature crossing</td><td><a href="/torch-rechub/tutorials/models/ranking/dcn.html">DCN</a></td></tr><tr><td>DIN</td><td>Target-aware attention over user history</td><td><a href="/torch-rechub/tutorials/models/ranking/din.html">DIN</a></td></tr><tr><td>DIEN</td><td>Interest evolution modeling</td><td><a href="/torch-rechub/tutorials/models/ranking/dien.html">DIEN</a></td></tr><tr><td>BST</td><td>Transformer-based sequence ranking</td><td><a href="/torch-rechub/tutorials/models/ranking/bst.html">BST</a></td></tr></tbody></table><h3 id="retrieval-models" tabindex="-1">Retrieval Models <a class="header-anchor" href="#retrieval-models" aria-label="Permalink to “Retrieval Models”">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Summary</th><th>Link</th></tr></thead><tbody><tr><td>DSSM</td><td>Classic two-tower semantic matching</td><td><a href="/torch-rechub/tutorials/models/matching/dssm.html">DSSM</a></td></tr><tr><td>YoutubeDNN</td><td>YouTube-style deep retrieval</td><td><a href="/torch-rechub/tutorials/models/matching/youtube_dnn.html">YoutubeDNN</a></td></tr><tr><td>MIND</td><td>Multi-interest retrieval with capsules</td><td><a href="/torch-rechub/tutorials/models/matching/mind.html">MIND</a></td></tr></tbody></table><h3 id="multi-task-models" tabindex="-1">Multi-Task Models <a class="header-anchor" href="#multi-task-models" aria-label="Permalink to “Multi-Task Models”">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Summary</th><th>Link</th></tr></thead><tbody><tr><td>MMOE</td><td>Multi-gate mixture-of-experts</td><td><a href="/torch-rechub/tutorials/models/multi_task/mmoe.html">MMOE</a></td></tr><tr><td>PLE</td><td>Progressive layered extraction</td><td><a href="/torch-rechub/tutorials/models/multi_task/ple.html">PLE</a></td></tr></tbody></table>',12)])])}const b=e(i,[["render",l]]);export{m as __pageData,b as default};
